# AG(3,2) family (odd-weight vectors of F_2^4): image Lambda_F cap [-j,j]^8; is J generated by grid + its circuits?
import itertools, sys, flint
from fractions import Fraction
from rlib import *
from echelon import Ech
j=int(sys.argv[1]); Dmax=int(sys.argv[2])
t=4
V=[a for a in itertools.product((0,1),repeat=t) if any(a)]
F=[a for a in V if sum(a)%2==1]
dot=lambda a,z: sum(x*y for x,y in zip(a,z))%2
MF=flint.fmpz_mat([[dot(a,z) for z in V] for a in F])     # 8 x 15
H=MF.transpose().hnf()          # rows span the lattice (as row vectors)
B=flint.fmpz_mat([[H[i,c] for c in range(8)] for i in range(8)])   # first 8 rows nonzero
assert abs(B.det())==32, B.det()
Binv=B.transpose().inv()   # fmpq
def inlat(y):
    v=Binv*flint.fmpq_mat([[x] for x in y])
    return all(v[i,0].q==1 for i in range(8))
b=8; cap=[2*j+1]*b
P=[y for y in itertools.product(range(-j,j+1),repeat=b) if inlat(y)]
print("|P| =",len(P))
# check description: parity on all codewords + sum = 0 mod 4
codes=[s for s in itertools.product((0,1),repeat=b) if any(s) and all(x==0 for x in [sum(F[i][q] for i in range(b) if s[i])%2 for q in range(t)])]
P2=[y for y in itertools.product(range(-j,j+1),repeat=b) if all(sum(y[i] for i in range(b) if s[i])%2==0 for s in codes) and sum(y)%4==0]
print("description parity+sum mod 4 matches:",sorted(P)==sorted(P2),"; #codewords",len(codes))
circ=[s for s in codes if not any(u!=s and all(ui<=si for ui,si in zip(u,s)) for u in codes)]
print("circuit sizes",sorted(sum(s) for s in circ))
hs=[];e=0
while e<=Dmax:
    hs.append(h_func_exact(P,e,cap)); e+=1
    if hs[-1]==len(P): break
Hf=[hs[0]]+[hs[i]-hs[i-1] for i in range(1,len(hs))]
print("H_P",Hf,"rho",len(Hf)-1 if hs[-1]==len(P) else ">%d"%Dmax)
target=[len(monos_eq(b,D,cap))-(Hf[D] if D<len(Hf) else 0) for D in range(min(Dmax,2*j*b)+1)]
loc={}
for s in circ:
    idx=[q for q in range(b) if s[q]]; c=len(idx)
    Ps=[y for y in itertools.product(range(-j,j+1),repeat=c) if sum(y)%2==0]
    gl={}
    for e in range(1,min(Dmax,2*j*c)+1):
        sp=J_space(Ps,e,[2*j+1]*c)
        if sp: gl[e]=[{tuple(ex[idx.index(q)] if q in idx else 0 for q in range(b)):v for ex,v in g.items()} for g in sp]
    loc[s]=gl
gens={}
for s in circ:
    for e,gl in loc[s].items(): gens.setdefault(e,[]).extend(gl)
for D in range(len(target)):
    E=Ech()
    for r in ideal_degree_rows(gens,b,D,cap): E.add(r)
    print("D",D,"target",target[D],"grid+circuits (mod p lower bound)",E.rank()); sys.stdout.flush()
# exact ranks + width powers of all primitive {-1,0,1}^8 directions
from math import gcd
wp={}
for v in itertools.product((-1,0,1),repeat=b):
    if not any(v) or [x for x in v if x][0]<0: continue
    vals=set(sum(a*x for a,x in zip(v,y)) for y in P)
    if len(vals)<=Dmax:
        wp.setdefault(len(vals),[]).append(pullback({(len(vals),):1},[v],b))
print("width powers by degree",{e:len(l) for e,l in sorted(wp.items())})
allg={e:list(gens.get(e,[]))+list(wp.get(e,[])) for e in set(gens)|set(wp)}
for D in range(4,9):
    cols=monos_eq(b,D,cap)
    r1=rank_rows(ideal_degree_rows(gens,b,D,cap),cols,modp=False)
    r2=rank_rows(ideal_degree_rows(allg,b,D,cap),cols,modp=False)
    print("D",D,"target",target[D],"EXACT grid+circuits",r1,"EXACT +width powers {-1,0,1}",r2); sys.stdout.flush()
